import argparse
import json
import sys
import tomllib


def inspect_project(text):
    document = tomllib.loads(text)
    project = document.get('project')
    if not isinstance(project, dict):
        raise ValueError('project table required')
    name = project.get('name')
    if not isinstance(name, str) or not name.strip():
        raise ValueError('project.name must be nonempty text')
    version = project.get('version')
    requires_python = project.get('requires-python')
    for value in (version, requires_python):
        if value is not None and not isinstance(value, str):
            raise ValueError('version and requires-python must be text when supplied')
    dependencies = project.get('dependencies', [])
    if not isinstance(dependencies, list) or any(not isinstance(item, str) for item in dependencies):
        raise ValueError('dependencies must be a text array')
    scripts = project.get('scripts', {})
    if not isinstance(scripts, dict) or any(not isinstance(value, str) for value in scripts.values()):
        raise ValueError('scripts must map names to text')
    return {'name': name, 'version': version, 'requires_python': requires_python,
            'dependency_count': len(dependencies), 'dependencies': sorted(dependencies),
            'scripts': sorted(scripts)}


def main():
    parser = argparse.ArgumentParser(description='Inspect pyproject.toml supplied on stdin; never installs or imports a project.')
    parser.parse_args()
    text = '' if sys.stdin.isatty() else sys.stdin.read()
    if not text.strip():
        parser.print_help()
        return 0
    try:
        result = inspect_project(text)
    except ValueError as error:
        print(str(error), file=sys.stderr)
        return 2
    print(json.dumps(result, sort_keys=True, ensure_ascii=True))
    return 0


if __name__ == '__main__':
    raise SystemExit(main())
